/**
 * Start TOTP enrollment
 *
 * Returns the `otpauth://` URI and the base32 secret for the enrollment
 * wizard (e.g. to render a QR code). This is the ONLY response that ever
 * returns the raw secret.
 *
 */
export const beginTotpEnrollment = <ThrowOnError extends boolean = false>(
  options?: Options<BeginTotpEnrollmentData, ThrowOnError>,
) =>
  (options?.client ?? client).post<
    BeginTotpEnrollmentResponses,
    BeginTotpEnrollmentErrors,
    ThrowOnError
  >({ url: "/auth/2fa/totp/begin", ...options });

/**
 * Confirm TOTP enrollment with a live code
 *
 * Validates `code` against the provisional secret from
 * `POST /auth/2fa/totp/begin`, persists the confirmed secret, and
 * returns 10 recovery codes shown exactly once.
 *
 */
export const confirmTotpEnrollment = <ThrowOnError extends boolean = false>(
  options: Options<ConfirmTotpEnrollmentData, ThrowOnError>,
) =>
  (options.client ?? client).post<
    ConfirmTotpEnrollmentResponses,
    ConfirmTotpEnrollmentErrors,
    ThrowOnError
  >({
    url: "/auth/2fa/totp/confirm",
    ...options,
    headers: {
      "Content-Type": "application/json",
      ...options.headers,
    },
  });

/**
 * Disable TOTP
 *
 * Requires `current_password` re-authentication. On success: clears
 * TOTP, recomputes `two_factor_enabled`, revokes every trusted device
 * for this user, and clears the trusted-device cookie on this response.
 *
 */
